import{_ as n,C as t,o as e,c as p,E as d,a2 as l}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"架构概览","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":null}'),i={name:"architecture.md"};function r(o,a,c,h,u,b){const s=t("VersionBadge");return e(),p("div",null,[d(s),a[0]||(a[0]=l(`<h1 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h1><p>本文档面向需要深入理解 Exero 内部机制的开发者和 AI 协作助手。读完本文档，你将理解 Exero 的整体架构、扩展系统设计、数据流和关键设计决策。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>应用框架</td><td>Tauri v2</td><td>跨平台桌面应用框架，Rust 后端 + WebView 前端</td></tr><tr><td>后端语言</td><td>Rust (stable, edition 2021)</td><td>LTSC 版本，x64</td></tr><tr><td>前端框架</td><td>React 18 + TypeScript</td><td>Vite 构建，shadcn/ui + Radix + Tailwind CSS</td></tr><tr><td>可视化编辑器</td><td>React Flow (@xyflow/react)</td><td>拖拽连线式工作流编辑器</td></tr><tr><td>数据库</td><td>SQLite (rusqlite + refinery)</td><td>WAL 模式，便携式存储</td></tr><tr><td>Lua 引擎</td><td>LuaJIT (mlua crate)</td><td>严格沙箱，10 秒超时</td></tr><tr><td>动态库加载</td><td>libloading + C ABI</td><td>运行时加载 .dll，extern &quot;C&quot; 接口</td></tr><tr><td>状态管理</td><td>Zustand</td><td>轻量级状态管理</td></tr><tr><td>包管理器</td><td>pnpm</td><td>corepack 管理</td></tr></tbody></table><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ Exero 主窗口 (React SPA) ──────────────────────────────────┐</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ Sidebar ──┐  ┌─ 主内容区 ──────────────────────────────┐ │</span></span>
<span class="line"><span>│  │ 首页        │  │                                          │ │</span></span>
<span class="line"><span>│  │ 时间轴      │  │  5 大页面：                              │ │</span></span>
<span class="line"><span>│  │ 快捷指令    │  │  1. Dashboard（系统状态+任务预览）        │ │</span></span>
<span class="line"><span>│  │ 性能优化    │  │  2. 时间轴（日/周/月/年四视图）           │ │</span></span>
<span class="line"><span>│  │ 设置        │  │  3. 快捷指令（Flow 编辑器+执行日志）     │ │</span></span>
<span class="line"><span>│  │ ─────────  │  │  4. 性能优化（硬件监控+进程管理）         │ │</span></span>
<span class="line"><span>│  │ 📌 插件入口 │  │  5. 设置（外观/通用/更新/关于/帮助）     │ │</span></span>
<span class="line"><span>│  └────────────┘  └──────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ 扩展系统 ──────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  ActionExecutorRegistry (动作执行器注册表)               │ │</span></span>
<span class="line"><span>│  │  ├── 内置 20 种 ActionType                               │ │</span></span>
<span class="line"><span>│  │  ├── Lua 执行器 (LuaJIT 沙箱)                            │ │</span></span>
<span class="line"><span>│  │  └── Rust 执行器 (libloading .dll + C ABI)              │ │</span></span>
<span class="line"><span>│  │                                                          │ │</span></span>
<span class="line"><span>│  │  ExtensionPackRegistry (扩展包注册表)                    │ │</span></span>
<span class="line"><span>│  │  ├── builtin: &lt;exe_dir&gt;/data/action-packs/              │ │</span></span>
<span class="line"><span>│  │  ├── user: %APPDATA%/Exero/action-packs/                │ │</span></span>
<span class="line"><span>│  │  └── custom: settings extension_pack.user_dir           │ │</span></span>
<span class="line"><span>│  │                                                          │ │</span></span>
<span class="line"><span>│  │  RustLibraryRegistry (Rust .dll 注册表)                  │ │</span></span>
<span class="line"><span>│  │  └── LoadLibrary + exero_pack_init + exero_execute_action│ │</span></span>
<span class="line"><span>│  └──────────────────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  ┌─ 插件 UI ───────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  PluginPage → iframe (http://plugin.localhost/{id}/)    │ │</span></span>
<span class="line"><span>│  │  ├── 桥接脚本注入 (window.exero.invoke)                  │ │</span></span>
<span class="line"><span>│  │  └── postMessage ↔ execute_plugin_action → .dll          │ │</span></span>
<span class="line"><span>│  └──────────────────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>┌─ Rust 后端 (Tauri Commands) ─────────────────────────────────┐</span></span>
<span class="line"><span>│  数据库层 (rusqlite + refinery)                              │</span></span>
<span class="line"><span>│  ├── 流程数据 5 表 (flows/actions/triggers/logs/settings)   │</span></span>
<span class="line"><span>│  └── 课程数据 5 表 (semesters/periods/templates/courses/...) │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  触发器调度器 (tokio)                                        │</span></span>
<span class="line"><span>│  ├── Cron 定时触发                                           │</span></span>
<span class="line"><span>│  ├── 系统事件触发 (开机/关机/USB/网络/进程)                  │</span></span>
<span class="line"><span>│  └── 手动触发 (首页/托盘)                                    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  动作执行引擎                                                │</span></span>
<span class="line"><span>│  ├── 顺序执行 + 条件分支 + 循环 + 变量传递                   │</span></span>
<span class="line"><span>│  ├── 容错策略 (继续/停止/回滚/通知)                          │</span></span>
<span class="line"><span>│  └── 动作超时 (Lua 默认 10s)                                 │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="扩展系统架构" tabindex="-1">扩展系统架构 <a class="header-anchor" href="#扩展系统架构" aria-label="Permalink to &quot;扩展系统架构&quot;">​</a></h2><h3 id="两种扩展形态对比" tabindex="-1">两种扩展形态对比 <a class="header-anchor" href="#两种扩展形态对比" aria-label="Permalink to &quot;两种扩展形态对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>动作包 (Action Pack)</th><th>插件 (Plugin)</th></tr></thead><tbody><tr><td><strong>pack_type</strong></td><td><code>&quot;action&quot;</code></td><td><code>&quot;plugin&quot;</code></td></tr><tr><td><strong>后端语言</strong></td><td>Rust (.dll) 或 Lua (.lua)</td><td>必须 Rust (.dll)</td></tr><tr><td><strong>UI 页面</strong></td><td>无</td><td>有 (iframe)</td></tr><tr><td><strong>侧边栏入口</strong></td><td>无</td><td>有（独占）</td></tr><tr><td><strong>Flow 积木</strong></td><td>有</td><td>可选（附带动作）</td></tr><tr><td><strong>适用场景</strong></td><td>纯动作扩展</td><td>完整功能页面</td></tr></tbody></table><h3 id="动作执行流程" tabindex="-1">动作执行流程 <a class="header-anchor" href="#动作执行流程" aria-label="Permalink to &quot;动作执行流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户触发 (Cron/系统事件/手动)</span></span>
<span class="line"><span>  → Trigger 调度器</span></span>
<span class="line"><span>  → 加载 AutomationFlow</span></span>
<span class="line"><span>  → 按 actions 顺序执行</span></span>
<span class="line"><span>    → ActionExecutorRegistry 查找执行器</span></span>
<span class="line"><span>      ├── 内置 ActionType (LaunchProgram/SetVolume/Shutdown...)</span></span>
<span class="line"><span>      ├── Lua 执行器 (LuaJIT 沙箱执行 .lua)</span></span>
<span class="line"><span>      └── Rust 执行器 (libloading 调用 .dll 导出函数)</span></span>
<span class="line"><span>    → 返回 ActionResult (output + status)</span></span>
<span class="line"><span>    → 容错策略判断 (继续/停止/回滚/通知)</span></span>
<span class="line"><span>  → 写入 execution_logs</span></span></code></pre></div><h3 id="插件-ui-桥接流程" tabindex="-1">插件 UI 桥接流程 <a class="header-anchor" href="#插件-ui-桥接流程" aria-label="Permalink to &quot;插件 UI 桥接流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户点击侧边栏插件入口</span></span>
<span class="line"><span>  → PluginPage 组件加载</span></span>
<span class="line"><span>  → iframe src=&quot;http://plugin.localhost/{pack_id}/index.html&quot;</span></span>
<span class="line"><span>  → Tauri 自定义协议处理器</span></span>
<span class="line"><span>    → 验证插件已安装 (ExtensionPackRegistry)</span></span>
<span class="line"><span>    → 读取 HTML 文件</span></span>
<span class="line"><span>    → 在 &lt;/head&gt; 前注入桥接脚本 (inject_bridge_script)</span></span>
<span class="line"><span>    → 返回 HTML</span></span>
<span class="line"><span>  → iframe 渲染插件页面</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户在插件页面调用 window.exero.invoke(actionId, params)</span></span>
<span class="line"><span>  → 桥接脚本 postMessage({ type: &#39;exero-invoke&#39;, id, actionId, params })</span></span>
<span class="line"><span>  → PluginPage 监听 message 事件</span></span>
<span class="line"><span>  → 调用 Tauri 命令 execute_plugin_action(pack_id, action_id, params)</span></span>
<span class="line"><span>  → RustLibraryRegistry::execute (C ABI 调用 .dll)</span></span>
<span class="line"><span>  → postMessage({ type: &#39;exero-result&#39;, id, result|error })</span></span>
<span class="line"><span>  → 桥接脚本 resolve Promise</span></span></code></pre></div><h3 id="rust-dll-c-abi-接口" tabindex="-1">Rust .dll C ABI 接口 <a class="header-anchor" href="#rust-dll-c-abi-接口" aria-label="Permalink to &quot;Rust .dll C ABI 接口&quot;">​</a></h3><p>SDK 的 <code>declare_actions!</code> 宏自动生成 4 个导出函数：</p><table tabindex="0"><thead><tr><th>函数</th><th>签名</th><th>说明</th></tr></thead><tbody><tr><td><code>exero_pack_init</code></td><td><code>() -&gt; i32</code></td><td>加载时调用，返回 0 表示成功</td></tr><tr><td><code>exero_pack_cleanup</code></td><td><code>() -&gt; void</code></td><td>卸载时调用</td></tr><tr><td><code>exero_execute_action</code></td><td><code>(action_id, params_json) -&gt; *const c_char</code></td><td>执行动作，返回 JSON 字符串</td></tr><tr><td><code>exero_last_error</code></td><td><code>() -&gt; *const c_char</code></td><td>获取最近一次错误信息</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全模型</p><p>.dll 加载无沙箱隔离，可完全访问系统（与 Lua 宽松沙箱同级风险）。用户自担风险安装第三方插件。.dll 必须编译为 <code>x86_64-pc-windows-msvc</code> 目标。</p></div><h2 id="数据库架构" tabindex="-1">数据库架构 <a class="header-anchor" href="#数据库架构" aria-label="Permalink to &quot;数据库架构&quot;">​</a></h2><h3 id="流程数据-5-表" tabindex="-1">流程数据（5 表） <a class="header-anchor" href="#流程数据-5-表" aria-label="Permalink to &quot;流程数据（5 表）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>用途</th><th>关键字段</th></tr></thead><tbody><tr><td><code>automation_flows</code></td><td>快捷指令</td><td>id, name, icon, enabled</td></tr><tr><td><code>actions</code></td><td>动作块</td><td>id, flow_id, type, params, order, parent_id, fault_strategy</td></tr><tr><td><code>triggers</code></td><td>触发器</td><td>id, flow_id, type, params, enabled</td></tr><tr><td><code>execution_logs</code></td><td>执行日志</td><td>id, flow_id, action_id, status, started_at, finished_at, error</td></tr><tr><td><code>settings</code></td><td>设置</td><td>key, value, type</td></tr></tbody></table><h3 id="课程数据-5-表-与流程数据解耦" tabindex="-1">课程数据（5 表，与流程数据解耦） <a class="header-anchor" href="#课程数据-5-表-与流程数据解耦" aria-label="Permalink to &quot;课程数据（5 表，与流程数据解耦）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表</th><th>用途</th></tr></thead><tbody><tr><td><code>semesters</code></td><td>学期定义</td></tr><tr><td><code>class_periods</code></td><td>节次时间表</td></tr><tr><td><code>weekly_templates</code></td><td>周课表模板（普通周/特殊周）</td></tr><tr><td><code>courses</code></td><td>课程实体（归属周模板）</td></tr><tr><td><code>schedule_overrides</code></td><td>临时调课记录（单次生效）</td></tr></tbody></table><h2 id="扩展包加载策略" tabindex="-1">扩展包加载策略 <a class="header-anchor" href="#扩展包加载策略" aria-label="Permalink to &quot;扩展包加载策略&quot;">​</a></h2><h3 id="三目录扫描-优先级从高到低" tabindex="-1">三目录扫描（优先级从高到低） <a class="header-anchor" href="#三目录扫描-优先级从高到低" aria-label="Permalink to &quot;三目录扫描（优先级从高到低）&quot;">​</a></h3><ol><li><strong>builtin</strong>：<code>&lt;exe_dir&gt;/data/action-packs/</code>（只读）</li><li><strong>user</strong>：<code>%APPDATA%/Exero/action-packs/</code>（可写）</li><li><strong>custom</strong>：settings <code>extension_pack.user_dir</code>（可选）</li></ol><p>同名扩展包先加载的优先（builtin &gt; user &gt; custom）。</p><h3 id="市场分发" tabindex="-1">市场分发 <a class="header-anchor" href="#市场分发" aria-label="Permalink to &quot;市场分发&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Market/</span></span>
<span class="line"><span>├── market-index.json          # 元数据索引（list_market_packs 只下载此文件）</span></span>
<span class="line"><span>├── action-packs/              # 动作包 .exero-pack</span></span>
<span class="line"><span>└── plugins/                   # 插件 .exero-pack</span></span></code></pre></div><p>网络后备：github.com → ghproxy 镜像 → 离线模式（仅已安装）</p><h2 id="关键设计决策摘要" tabindex="-1">关键设计决策摘要 <a class="header-anchor" href="#关键设计决策摘要" aria-label="Permalink to &quot;关键设计决策摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>原因</th></tr></thead><tbody><tr><td>C ABI 而非 Rust ABI</td><td>Rust 自身 ABI 不稳定，C ABI 保证兼容性</td></tr><tr><td>iframe + postMessage</td><td>天然隔离，插件崩溃不影响主程序</td></tr><tr><td>不允许 <code>allow-same-origin</code></td><td>防止插件访问 Exero 主窗口 DOM</td></tr><tr><td>LuaJIT 而非标准 Lua</td><td>性能最优，对自动化脚本几乎无损耗</td></tr><tr><td>market-index.json 索引</td><td>只下载 1 个文件而非逐个下载 zip，减少网络请求</td></tr><tr><td>三目录扫描</td><td>builtin（内置）+ user（用户安装）+ custom（自定义路径）</td></tr><tr><td>courses 表同时存 period_index 和 time</td><td>拖拽时两个字段互斥更新，兼顾课表定位和精确时间</td></tr></tbody></table><p>更多设计决策详见 <a href="/spec-summary">SPEC 摘要</a>。</p>`,32))])}const _=n(i,[["render",r]]);export{m as __pageData,_ as default};
